steps.sampleSolution:
#include <Eigen/Dense>
#include <iostream>

int main() {
    Eigen::Vector3d a(1, 2, 3);
    Eigen::Vector3d b(4, 5, 6);
    double esc = a.dot(b);
    std::cout << esc << "\n";
    return 0;
}
